import { StyleSheet, View } from 'react-native';

import { Button, Card, Icon, Text } from '@/components';
import { useT } from '@/i18n';
import { useTheme } from '@/theme';

/**
 * Where a result would go — the end of the intake, and of the image flow.
 *
 * ── The most important component in this directory ──────────────────
 *
 * This is the exact spot where a "finished-looking" feature would put a
 * sentence like *"Your symptoms suggest…"*, generated by nothing, and
 * call Phase K done. It does not. It says, in the place the result would
 * occupy, that no assistant has read anything the patient entered and
 * that nothing has been sent anywhere — and then offers the two routes
 * that are real: a clinician, and the emergency screen.
 *
 * That is not a lesser version of the feature. A patient who has just
 * typed out what is wrong with them is owed a true statement about what
 * happened to it, and "a person should look at this" is better advice
 * than anything an unreviewed model would have produced.
 *
 * ── Why the summary is echoed back ──────────────────────────────────
 *
 * `summary` is what the patient themselves selected, rendered back to
 * them so the screen is not simply a refusal — they can check it, and
 * they can read it out at a desk or over the phone. It is their own
 * input, not an interpretation of it, and it is never labelled as a
 * finding. It is not persisted: it lives in the screen's state and is
 * gone when the screen is (T-03 — this client writes no PHI to disk).
 */
export interface AiResultPlaceholderProps {
  /** The patient's own selections, echoed. Never an interpretation. */
  readonly summary?: readonly string[];
  readonly onFindCare: () => void;
  readonly onEmergency: () => void;
  readonly testID?: string;
}

export function AiResultPlaceholder({
  summary,
  onFindCare,
  onEmergency,
  testID,
}: AiResultPlaceholderProps) {
  const theme = useTheme();
  const t = useT();

  return (
    <Card tone="info" testID={testID ?? 'ai-result-placeholder'}>
      <View style={[styles.row, { columnGap: theme.space[2] }]}>
        <Icon name="info" size={20} color="info" />
        <Text variant="h3" color="info" style={styles.grow}>
          {t('ai.result.title')}
        </Text>
      </View>

      <Text variant="bodySm" color="textSecondary">
        {t('ai.result.body')}
      </Text>
      <Text variant="bodySm" color="textSecondary">
        {t('ai.result.notSent')}
      </Text>

      {summary === undefined || summary.length === 0 ? null : (
        <View
          testID="ai-result-summary"
          accessible
          accessibilityLabel={t('ai.result.summaryA11y', { items: summary.join(', ') })}
          style={[
            styles.summary,
            {
              backgroundColor: theme.colors.surface,
              borderColor: theme.colors.border,
              borderRadius: theme.radius.surface,
              padding: theme.space[3],
              rowGap: theme.space[1],
            },
          ]}
        >
          <Text variant="label" color="textSecondary">
            {t('ai.result.summaryTitle')}
          </Text>
          {summary.map((line) => (
            <Text key={line} variant="bodySm">
              {line}
            </Text>
          ))}
        </View>
      )}

      <Button
        testID="ai-result-find-care"
        label={t('ai.result.findCare')}
        tone="primary"
        icon="search"
        fullWidth
        onPress={onFindCare}
      />
      <Button
        testID="ai-result-emergency"
        label={t('ai.safety.emergency.action')}
        tone="emergency"
        icon="alert"
        fullWidth
        onPress={onEmergency}
        hint={t('ai.safety.emergency.hint')}
      />
    </Card>
  );
}

const styles = StyleSheet.create({
  grow: { flex: 1 },
  row: { alignItems: 'center', flexDirection: 'row' },
  summary: { borderWidth: 1 },
});
